F cd.i_B loadTargetPercent HIGH  # set 10/20/50/90/100 during c(); loading bar
F cd.j_B loadShownPercent HIGH  # increments toward i_B; bar x = 15+(w-30)*j_B/100
F cd.a_S mapWidth HIGH  # = ca.b_S() (pixel width); camera clamp i_S <= a_S-screenW
F cd.b_S mapHeight HIGH  # = ca.a_S() (pixel height)
