F cd.j_S cameraY HIGH  # follows player e_S - screenH/2
F cd.b_I mapOffsetX HIGH  # (screenW-mapWidth)/2 when map narrower than screen
F cd.c_I mapOffsetY HIGH  # (screenH-mapHeight)/2
